const EMPTY = Array(64).fill('.'.repeat(64));
export function composeHero64(look) {
  const N = 64, b = look.body === 'f' ? 'f' : 'm', hs = look.hair || 'short', rc = look.race || 'human', covered = hs === 'hood' || hs === 'crown';
  const R = RACE[rc][b], Wp = WEAPON[look.weapon || 'sword'][b], C = CLASS[look.cls]?.[b];
  const src = { ...BASE[b], ...HAIR[hs][b], raceBack: R.raceBack, raceFace: R.raceFace,
    raceHead: hs === 'hood' ? R.raceHeadHood : hs === 'crown' ? R.raceHeadCrown : R.raceHead,
    weapon: Wp.hand, weaponBack: Wp.back, outfitOver: OUTFIT[look.outfit]?.[b] || EMPTY,
    classFront: C ? C.classFront : EMPTY, classHead: C ? (covered ? C.classHeadCovered : C.classHead) : EMPTY,
    classBack: C ? C.classBack : EMPTY, skinOver: SKINSET[look.skinSet]?.[b] || EMPTY };
  if (CAPE_REPLACE.includes(look.cls)) { src.capeBack = EMPTY; src.capeFront = EMPTY; }
  const g = [...Array(N)].map(() => Array(N).fill('.'));
  for (const ln of LAYER_ORDER) {
    if (ln === 'weapon' && look.mount === 'back') continue;
    if (ln === 'weaponBack' && look.mount !== 'back') continue;
    src[ln].forEach((r, y) => { for (let x = 0; x < N; x++) if (r[x] !== '.') g[y][x] = r[x]; });
  }
  const lk = { ...look, ...(SKIN_PAL[look.skinSet] || {}) };
  const pal = { ...FIXED_PAL }, base = { ...lk, S: RACE_SKIN[rc] || lk.S, C: lk.C || capeOf(lk.O) };
  if (rc === 'shade') for (const f of SHADE_TINT) base[f] = mix(base[f], '#120a1e', 0.72);
  for (const [fam, ch] of Object.entries(FAMILY_KEYS)) ramp4(base[fam]).forEach((c, i) => { pal[ch[i]] = c; });
  if (rc === 'shade') for (const f of SHADE_LIT) pal[FAMILY_KEYS[f][3]] = mix(pal[FAMILY_KEYS[f][2]], '#a07ce8', 0.5);
  const full = (x, y) => x >= 0 && x < N && y >= 0 && y < N && g[y][x] !== '.';
  const POOL = [...Array(94)].map((_, i) => String.fromCharCode(33 + i)).filter(c => c !== '.'), cmap = new Map();
  const key = col => { if (!cmap.has(col)) cmap.set(col, POOL[cmap.size]); return cmap.get(col); };
  const rows = [];
  for (let y = 0; y < N; y++) { let row = '';
    for (let x = 0; x < N; x++) {
      if (!full(x, y)) { row += [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([a, c]) => full(x + a, y + c)) ? key(OUTLINE) : '.'; continue; }
      let c = pal[g[y][x]];
      if (x >= N / 2 && !full(x + 1, y) && !full(x + 2, y)) c = mix(c, RIM, 0.55);
      row += key(c);
    } rows.push(row); }
  return { rows, pal: Object.fromEntries([...cmap].map(([c, ch]) => [ch, c])) };
}
